def test_ctl(content, inp_bytes):
    open("/tmp/testctl.flc","w").write(content)
    o,e,rc=run_bytes(["-d","/tmp","-C","testctl"], inp_bytes)
    return s(o), s(e), rc

# Get reference figs for various chars
def get_fig(ch):
    # ch as bytes? Use standard without control
    o,_,_=run_bytes(["-d","/tmp"], ch.encode('latin1')+b"\n" if isinstance(ch,str) else ch+b"\n")
    return s(o)

for ch in ["A","a","B","b","c","C","X","Y","Z","e","E","é","É"]:
    print(f"{repr(ch)} -> {repr(get_fig(ch)[:80])}")

