    /* defaults */
    char *envdir = getenv("FIGLET_FONTDIR");
    if (envdir) fontdir_val = strdup(envdir);
    else fontdir_val = strdup(DEFAULT_FONTDIR);
    fontname_val = strdup(DEFAULT_FONT);
    outputwidth_val = 80;
    justify_val = JUST_AUTO;
    direction_val = DIR_AUTO;
    layout_val = LAY_DEFAULT_S;
    layout_explicit_bits = 0;
    deutsch_val = 0;
    para_val = 0;
    info_code = -1;
    has_d_opt = 0;
    control_count = 0;

    /* getopt string: valid opts + A (ignore) + F (special) */
    /* valid single: c k l n o p r s t v x D E L N R S W X A F */
    /* with args: d f m w C I */
    const char *optstr = "cklnoprstvxDELNRSWXA:d:f:m:w:C:I:F";
    int c;
    /* need to handle -t ioctl etc. during parsing for outputwidth */
    while ((c = getopt(argc, argv, optstr)) != -1) {
        switch (c) {
            case 'c': justify_val = JUST_CENTER; break;
            case 'l': justify_val = JUST_LEFT; break;
            case 'r': justify_val = JUST_RIGHT; break;
            case 'x': justify_val = JUST_AUTO; break;
            case 'L': direction_val = DIR_LTR; break;
            case 'R': direction_val = DIR_RTL; break;
            case 'X': direction_val = DIR_AUTO; break;
            case 'D': deutsch_val = 1; break;
            case 'E': deutsch_val = 0; break;
            case 'p': para_val = 1; break;
            case 'n': para_val = 0; break;
            case 's': layout_val = LAY_DEFAULT_S; break;
            case 'S': layout_val = LAY_FORCE_S; break;
            case 'k': layout_val = LAY_KERN; break;
            case 'W': layout_val = LAY_FULL; break;
            case 'o': layout_val = LAY_OVERLAP; break;
            case 'v': info_code = 0; break;
            case 'N':
                control_count = 0;
                break;
            case 't': {
                /* try ioctl on stdout, stderr, stdin */
                struct winsize ws;
                int got = 0;
                if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0) {
                    outputwidth_val = ws.ws_col;
                    got = 1;
                } else if (ioctl(STDERR_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0) {
                    outputwidth_val = ws.ws_col;
                    got = 1;
                } else if (ioctl(STDIN_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0) {
                    outputwidth_val = ws.ws_col;
                    got = 1;
                } else {
                    /* retain previous, do nothing */
                }
                (void)got;
                break;
            }
            case 'd':
                free(fontdir_val);
                fontdir_val = strdup(optarg);
                has_d_opt = 1;
                break;
            case 'f':
                free(fontname_val);
                fontname_val = strdup(optarg);
                break;
            case 'w': {
                int w = atoi(optarg);
                if (w > 0) outputwidth_val = w;
                break;
            }
            case 'm': {
                int m = atoi(optarg);
                if (m == 0) { layout_val = LAY_KERN; }
                else if (m == -1) { layout_val = LAY_FULL; }
                else if (m < 0) { /* -2 and less (including -2,-3,...) => default S */
                    layout_val = LAY_DEFAULT_S;
