static void font_add(Font2 *f, int code, FigChar2 *fc) {
    /* if code already exists? First wins? For mandatory, no dup. For extra with dup codetags? First wins? Actually for extra, if duplicate codetags (e.g., upper has duplicate t lines? No, font extra duplicates? Unlikely. For safety, first wins (ignore dup). */
