static void print_outline(OutLine *ol, int h, int hb, int just, int outw) {
    int w = ol->widths[0];
    int lead=0;
    if (outw==1) lead=0;
    else {
        if (just==JUST_LEFT) lead=0;
        else if (just==JUST_RIGHT) { lead=outw-w-1; if (lead<0) lead=0; }
        else if (just==JUST_CENTER) { lead=(outw-w)/2; if (lead<0) lead=0; }
        else lead=0;
    }
    for (int r=0;r<h;r++) {
        for (int i=0;i<lead;i++) putchar(' ');
        int *row=ol->rows[r];
        int ww=ol->widths[r];
        for (int i=0;i<ww;i++) {
            int cp=row[i];
            if (cp==hb) cp=32;
            char buf[4]; int n=encode_utf8(cp,buf);
            fwrite(buf,1,n,stdout);
        }
        putchar('\n');
    }
}
