static unsigned char *build_message_input(int argc, char *argv[], int optind, size_t *out_len) {
    size_t cap=1024, len=0;
    unsigned char *buf=(unsigned char*)malloc(cap);
    for (int i=optind;i<argc;i++) {
        char *a=argv[i];
        size_t alen=strlen(a);
        if (alen==0) {
            if (len+1>=cap) { cap*=2; buf=(unsigned char*)realloc(buf,cap); }
            buf[len++]='\n';
        } else {
            if (len>0 && buf[len-1]!='\n') {
                if (len+1>=cap) { cap*=2; buf=(unsigned char*)realloc(buf,cap); }
                buf[len++]=' ';
            }
            while (len+alen>=cap) { cap*=2; buf=(unsigned char*)realloc(buf,cap); }
            memcpy(buf+len,a,alen); len+=alen;
        }
