static int decode_utf8_line(unsigned char *bytes, size_t blen, int *out_cps, size_t outcap) {
    size_t o=0; size_t i=0;
    while (i<blen && o<outcap) {
        unsigned char c0=bytes[i];
        if (c0<0x80) { out_cps[o++]=c0; i+=1; }
        else if ((c0&0xE0)==0xC0) {
            if (i+1>=blen || (bytes[i+1]&0xC0)!=0x80) { i+=1; continue; }
            int cp=((c0&0x1F)<<6)|(bytes[i+1]&0x3F);
            if (cp<0x80) { i+=1; continue; }
            out_cps[o++]=cp; i+=2;
        } else if ((c0&0xF0)==0xE0) {
            if (i+2>=blen || (bytes[i+1]&0xC0)!=0x80 || (bytes[i+2]&0xC0)!=0x80) { i+=1; continue; }
            int cp=((c0&0x0F)<<12)|((bytes[i+1]&0x3F)<<6)|(bytes[i+2]&0x3F);
            if (cp<0x800 || (cp>=0xD800&&cp<=0xDFFF)) { i+=1; continue; }
            out_cps[o++]=cp; i+=3;
        } else if ((c0&0xF8)==0xF0) {
            if (i+3>=blen || (bytes[i+1]&0xC0)!=0x80 || (bytes[i+2]&0xC0)!=0x80 || (bytes[i+3]&0xC0)!=0x80) { i+=1; continue; }
            int cp=((c0&0x07)<<18)|((bytes[i+1]&0x3F)<<12)|((bytes[i+2]&0x3F)<<6)|(bytes[i+3]&0x3F);
            if (cp<0x10000||cp>0x10FFFF) { i+=1; continue; }
            out_cps[o++]=cp; i+=4;
        } else { i+=1; continue; }
    }
    return (int)o;
}
